files.before:
package fixture

import "testing"
func TestNil(t *testing.T) { if Clone(nil) == nil { t.Fatal("nil") } }

files.after:
package fixture

import "testing"
func TestNil(t *testing.T) { if Clone(nil) != nil { t.Fatal("non-nil") } }

files.before:
package fixture

import "strings"
func Contains(s, q string) bool { return strings.Contains(s, q) }

files.after:
package fixture

import "strings"
func Contains(s, q string) bool { return strings.Contains(strings.ToLower(s), strings.ToLower(q)) }

files.before:
package fixture

import "strings"
func Before(a, b string) bool { return strings.Compare(a, b) < 0 }

files.after:
package fixture

import "strings"
func Before(a, b string) bool { return strings.Compare(a, b) > 0 }

support.contract.go:
package fixture

// The local flag codec contract requires FlagRoundtrip for both boolean values.
func FlagRoundtrip(v bool) bool { return DecodeFlag(EncodeFlag(v)) == v }

support.codec_test.go:
package fixture

import "testing"
func TestCodec(t *testing.T) { if !FlagRoundtrip(false) || !FlagRoundtrip(true) { t.Fatal("roundtrip") } }

files.after:
package fixture

func Unchanged() int { return 10 }
func RoundToTen(n int) int { return (n + 9) / 10 * 10 }

support.admission.go:
package fixture

// Admission is supplied by clients; its cross-resource constraints are unavailable.
type Admission func(cpu, memory int) bool
func Admitted(check Admission) bool { return check(CPUReservation(), MemoryReservation()) }

